#&gt;   variable   mean median     sd    mad     q5     q95  rhat ess_bulk ess_tail
#&gt;   &lt;chr&gt;     &lt;dbl&gt;  &lt;dbl&gt;  &lt;dbl&gt;  &lt;dbl&gt;  &lt;dbl&gt;   &lt;dbl&gt; &lt;dbl&gt;    &lt;dbl&gt;    &lt;dbl&gt;
#&gt; 1 p_ref     0.590  0.591 0.0216 0.0218  0.553  0.625   1.00     930.     853.
#&gt; 2 p_work    0.451  0.451 0.0129 0.0131  0.429  0.472   1.00    3201.    2589.
#&gt; 3 RD       -0.140 -0.140 0.0250 0.0248 -0.180 -0.0977  1.01     877.     873.
