# Questo ci dà accesso diretto ai valori campionati per ogni parametro
draws_mixture &lt;- fit_mixture$draws(format = "df")


# Produciamo un sommario statistico dei parametri principali del prior
prior_summary &lt;- fit_mixture$summary(c("theta", "tau1", "tau2"))
print(prior_summary)
