)


17.7.6 Preparazione dei dati per il confronto

# Estraiamo i campioni dalle posteriori di tutti i modelli
draws_flat &lt;- fit_flat$draws(format = "df")
draws_weakly &lt;- fit_weakly$draws(format = "df")

# Combiniamo i risultati in un unico dataset per facilitare il confronto
comparison_data &lt;- bind_rows(
  draws_bayesian |&gt; 
    select(beta, shrinkage_factor) |&gt; 
